export function AnimatedLogoMark() {
  const reduce = useReducedMotion();
  const wrapRef = useRef<HTMLDivElement>(null);

  const px = useMotionValue(0);
  const py = useMotionValue(0);
  const sx = useSpring(px, { stiffness: 110, damping: 18, mass: 0.6 });
  const sy = useSpring(py, { stiffness: 110, damping: 18, mass: 0.6 });
  const rotateY = useTransform(sx, [-0.5, 0.5], [-15, 15]);
  const rotateX = useTransform(sy, [-0.5, 0.5], [11, -11]);

  function onMove(e: React.MouseEvent<HTMLDivElement>) {
    if (reduce) return;
    const el = wrapRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    px.set((e.clientX - r.left) / r.width - 0.5);
    py.set((e.clientY - r.top) / r.height - 0.5);
  }

  return (
    <div
      ref={wrapRef}
      onMouseMove={onMove}
      onMouseLeave={() => {
        px.set(0);
        py.set(0);
      }}
      className="relative h-full w-full"
      style={{ perspective: 1000 }}
    >
      <motion.div
        className="relative h-full w-full"
        style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
        initial={{ opacity: 0, scale: 0.95, y: 14 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        transition={{ duration: 0.9, ease, delay: 0.1 }}
      >
        <div
          aria-hidden
          className="pointer-events-none absolute left-1/2 top-[58%] h-28 w-2/3 rounded-[50%] bg-gold/20 blur-3xl"
          style={{ transform: "translateX(-50%) translateZ(-80px)" }}
        />

        <motion.svg
          viewBox="0 0 617 554"
          className="relative h-full w-full"
          role="img"
          aria-label="Cup N Saucer"
          animate={reduce ? undefined : { y: [0, -8, 0] }}
          transition={{ duration: 7, repeat: Infinity, ease: "easeInOut" }}
          style={{
            filter:
              "drop-shadow(0 22px 30px rgba(79,58,20,0.28)) drop-shadow(0 6px 8px rgba(79,58,20,0.22))",
          }}
        >
          <defs>
            {/* vapour tint: bars stay solid at the base, lift toward the top */}
            <linearGradient
              id="vapour"
              gradientUnits="userSpaceOnUse"
              x1="0"
              y1="380"
              x2="0"
              y2="0"
            >
              <stop offset="0%" stopColor={GOLD} stopOpacity="1" />
              <stop offset="62%" stopColor={GOLD} stopOpacity="0.92" />
              <stop offset="100%" stopColor={GOLD} stopOpacity="0.6" />
            </linearGradient>

            {/* metallic bevel: light catches the top-left edge, shadow pools bottom-right */}
            <linearGradient
              id="bevel"
              gradientUnits="userSpaceOnUse"
              x1="130"
              y1="120"
              x2="470"
              y2="480"
            >
              <stop offset="0%" stopColor="#E7C989" />
              <stop offset="18%" stopColor="#C7A25E" />
              <stop offset="55%" stopColor={GOLD} />
              <stop offset="100%" stopColor="#6E5326" />
            </linearGradient>

            {/* soft inner shadow, clipped to each shape, for a pressed/embossed edge */}
            <clipPath id="cupClip">
              <path d={CUP.d} transform={`translate(${CUP.tx},${CUP.ty})`} />
            </clipPath>
            <clipPath id="handleClip">
              <path d={HANDLE.d} transform={`translate(${HANDLE.tx},${HANDLE.ty})`} />
            </clipPath>
          </defs>

          {/* cup + handle: the anchor, never animated away */}
          <g transform={`translate(${CUP.tx},${CUP.ty})`}>
            <path d={CUP.d} fill="url(#bevel)" />
          </g>
          <g clipPath="url(#cupClip)">
            <ellipse
              cx="230"
              cy="230"
              rx="230"
              ry="200"
              fill="#000"
              opacity="0.16"
              transform="translate(60,90)"
              style={{ filter: "blur(30px)" }}
            />
            <ellipse
              cx="60"
              cy="40"
              rx="140"
              ry="90"
              fill="#FFF3D8"
              opacity="0.35"
              transform="translate(110,110)"
              style={{ filter: "blur(26px)" }}
            />
          </g>

          <g transform={`translate(${HANDLE.tx},${HANDLE.ty})`}>
            <path d={HANDLE.d} fill="url(#bevel)" />
          </g>
          <g clipPath="url(#handleClip)">
            <ellipse
              cx="598"
              cy="340"
              rx="55"
              ry="60"
              fill="#000"
              opacity="0.18"
              style={{ filter: "blur(14px)" }}
            />
            <ellipse
              cx="530"
              cy="270"
              rx="40"
              ry="30"
              fill="#FFF3D8"
              opacity="0.4"
              style={{ filter: "blur(10px)" }}
            />
          </g>

          {/* the three bars, rising like steam */}
          <g>
            {BARS.map((bar, i) =>
              reduce ? (
                <g key={i} transform={`translate(${bar.tx},${bar.ty})`}>
                  <path d={bar.d} fill={GOLD} />
                </g>
              ) : (
                <g key={i} transform={`translate(${bar.tx},${bar.ty})`}>
                  <motion.path
                    d={bar.d}
                    fill="url(#vapour)"
                    style={{ transformOrigin: `50% ${bar.base}px` }}
                    initial={{ scaleY: 0, opacity: 0 }}
                    animate={{
                      scaleY: [0, 1, 1.03, 1],
                      opacity: [0, 1, 1, 1],
                      y: [0, 0, -3, 0],
                    }}
                    transition={{
                      scaleY: {
                        duration: 5.5,
                        times: [0, 0.22, 0.6, 1],
                        repeat: Infinity,
                        repeatDelay: 0.4,
                        delay: 0.35 + i * 0.14,
                        ease: "easeInOut",
                      },
                      opacity: {
                        duration: 5.5,
                        times: [0, 0.22, 0.6, 1],
                        repeat: Infinity,
                        repeatDelay: 0.4,
                        delay: 0.35 + i * 0.14,
                      },
                      y: {
                        duration: 5.5,
                        times: [0, 0.22, 0.6, 1],
                        repeat: Infinity,
                        repeatDelay: 0.4,
                        delay: 0.35 + i * 0.14,
                        ease: "easeInOut",
                      },
                    }}
                  />
                </g>
              ),
            )}
          </g>
        </motion.svg>
      </motion.div>
    </div>
  );
}
